import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:vizxr/services/kubeconfig.dart';
import 'package:vizxr/services/k8s_client.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    SharedPreferences.setMockInitialValues({});
  });

  const userYaml = '''apiVersion: v1
clusters:
- cluster:
    certificate-authority-data: 
    server: https://172.16.0.2:6443
  name: kubernetes
contexts:
- context:
    cluster: kubernetes
    user: kubernetes-admin
  name: kubernetes-admin@kubernetes
current-context: kubernetes-admin@kubernetes
kind: Config
users:
- name: kubernetes-admin
  user:
    client-certificate-data: 
    client-key-data: ''';

  test('parse user kubeconfig', () async {
    final config = await KubeConfig.addFromYaml(userYaml);
    print('CONFIG NAME: \${config.name}');
    print('CONFIG SERVER: \${config.server}');
    print('CA CERT LENGTH: \${config.caCert?.length}');
    print('CLIENT CERT LENGTH: \${config.clientCertData?.length}');
    print('CLIENT KEY LENGTH: \${config.clientKeyData?.length}');

    final client = K8sClientService(
      baseUrl: config.server,
      token: config.token,
      caCertData: config.caCert,
      clientCertData: config.clientCertData,
      clientKeyData: config.clientKeyData,
      insecureSkipTlsVerify: config.insecureSkipTlsVerify,
    );

    print('Client initialized successfully with mTLS context!');
  });
}
